import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import { Upload, Download, FileText, AlertTriangle, Server, HardDrive, Terminal } from 'lucide-react';

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [uploadStep, setUploadStep] = useState(0); // 0 = Idle
  const [error, setError] = useState(null);
  const [logs, setLogs] = useState([]); // This was missing!
  
  // Toggles
  const [storageMode, setStorageMode] = useState('local');
  const [cryptoMode, setCryptoMode] = useState('hybrid');

  useEffect(() => {
    fetchFiles();
  }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (err) { console.error("Fetch failed"); }
  };

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setError(null);
    setUploadStep(1);
    setLogs([]); // Clear logs on new upload
    
    addLog(`INIT: Secure Upload Protocol for ${file.name}`);

    // Simulation for Explainability
    setTimeout(() => { setUploadStep(2); addLog("PQC: Generating Ephemeral Kyber-512 Keys..."); }, 600);
    setTimeout(() => { setUploadStep(3); addLog("PQC: Encapsulating Shared Secret..."); }, 1200);
    setTimeout(() => { setUploadStep(4); addLog("KDF: Deriving AES-256-GCM Session Key..."); }, 1800);

    try {
      await uploadFile(file); 
      setUploadStep(5);
      addLog("AES: Encrypting File Payload...");
      addLog("UPLOAD: Transferring Encrypted Blob to Untrusted Storage...");
      
      setTimeout(() => {
        setUploadStep(0);
        addLog("SUCCESS: File Sealed & Stored.");
        fetchFiles();
      }, 1000);
    } catch (err) {
      setUploadStep(0);
      addLog("ERROR: Upload Failed.");
      setError("Upload Failed: Network or Server Error");
    }
  };

  const handleDownload = async (id, name) => {
    try {
      // 1. Visual Feedback
      addLog(`REQ: Access Request for File ID: ${id}`);
      addLog("NET: Retrieving Encrypted Blob...");
      
      // 2. The API Call
      await downloadFile(id, name);
      
      // 3. Success
      addLog("PQC: Decapsulation Successful (Shared Secret Recovered).");
      addLog("AES: Integrity Tag Verified.");
      addLog("IO: Decrypted Stream Released to User.");
      
    } catch (err) {
      console.error("Download Error:", err);
      
      // 4. Failure Visualization
      addLog("❌ FAILURE: Decryption Aborted.");
      addLog("❌ ALERT: Integrity Tag Mismatch Detected.");
      
      setError("CRITICAL: The file has been modified by an unauthorized party. Download aborted.");
    }
  };

  return (
    <div className="p-8 space-y-8">
      
      {/* HEADER & TOGGLES */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Secure Gateway</h2>
          <p className="text-gray-400 text-sm">Post-Quantum Cryptography Enabled</p>
        </div>
        
        <div className="flex gap-4">
            <div className="flex flex-col items-end">
            <label className="text-[10px] text-gray-500 uppercase mb-1">Experiment Mode</label>
            <select 
                value={cryptoMode} 
                onChange={(e) => setCryptoMode(e.target.value)}
                className="bg-scifi-panel border border-scifi-border text-xs text-neon-blue p-2 rounded focus:outline-none"
            >
                <option value="hybrid">Hybrid (PQC + AES)</option>
                <option value="rsa">RSA-2048 (Baseline)</option>
            </select>
          </div>

          <div className="flex flex-col items-end">
            <label className="text-[10px] text-gray-500 uppercase mb-1">Storage Backend</label>
            <button 
                onClick={() => setStorageMode(storageMode === 'local' ? 'minio' : 'local')}
                className="flex items-center gap-2 bg-scifi-panel border border-scifi-border text-xs text-neon-green p-2 rounded hover:bg-white/5"
            >
                {storageMode === 'local' ? <HardDrive size={14} /> : <Server size={14} />}
                {storageMode === 'local' ? 'Local Filesystem' : 'MinIO Cluster'}
            </button>
          </div>
        </div>
      </div>

      {/* ERROR BANNER */}
      {error && (
        <div className="bg-red-900/20 border border-red-500 p-4 rounded flex items-center gap-4 text-red-500 animate-pulse">
          <AlertTriangle size={24} />
          <div>
            <p className="font-bold">CRITICAL SECURITY ALERT</p>
            <p className="text-sm">{error}</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-3 gap-6">
        
        {/* LEFT COLUMN: UPLOAD & LOGS */}
        <div className="col-span-2 space-y-6">
            <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6">
                <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                <Upload size={18} className="text-neon-green" /> Secure Upload
                </h3>
                
                {uploadStep > 0 ? (
                <CryptoFlow currentStep={uploadStep} />
                ) : (
                <div className="border-2 border-dashed border-gray-700 rounded-lg p-10 text-center hover:border-neon-green transition-colors cursor-pointer relative">
                    <input type="file" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                    <div className="text-gray-500">
                    <p className="text-lg font-bold text-white mb-2">Drop files here to encrypt</p>
                    <p className="text-xs font-mono">PQC-KEM • AES-256 • HKDF</p>
                    </div>
                </div>
                )}
            </div>

            {/* TERMINAL VIEW (Added to show logs) */}
            <div className="bg-black border border-gray-800 rounded-xl p-4 h-48 overflow-y-auto font-mono text-xs">
                <div className="flex items-center gap-2 text-gray-500 border-b border-gray-800 pb-2 mb-2">
                    <Terminal size={14} /> CRYPTO_KERNEL_LOGS
                </div>
                {logs.length === 0 && <p className="text-gray-700 italic">System Idle...</p>}
                {logs.map((log, i) => (
                    <p key={i} className="text-neon-green/80 mb-1">{log}</p>
                ))}
            </div>
        </div>

        {/* RIGHT COLUMN: FILE LIST */}
        <div className="col-span-1 bg-scifi-panel border border-scifi-border rounded-xl p-6">
            <h3 className="text-white font-bold mb-4 flex items-center gap-2">
            <FileText size={18} className="text-neon-blue" /> Vault Contents
            </h3>
            <div className="space-y-2">
                {files.map(file => (
                    <div key={file.id} className="p-3 bg-white/5 rounded border border-transparent hover:border-neon-blue transition group">
                        <div className="flex justify-between items-start">
                            <p className="text-xs text-white truncate w-32 font-bold" title={file.filename}>{file.filename}</p>
                            <span className="text-[10px] bg-neon-green/20 text-neon-green px-1 rounded">SEALED</span>
                        </div>
                        <div className="flex justify-between items-center mt-2">
                            <span className="text-[10px] text-gray-500">{(file.size/1024).toFixed(2)} KB</span>
                            <button 
                                onClick={() => handleDownload(file.id, file.filename)}
                                className="text-gray-400 hover:text-neon-blue transition"
                            >
                                <Download size={16} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
